CREATE POLICY audit_admin_read ON public.access_audit_log AS PERMISSIVE FOR SELECT TO public USING (((tenant_id = current_tenant_id()) AND is_platform_admin()));
CREATE POLICY "Users can view own deletion requests" ON public.account_deletion_requests AS PERMISSIVE FOR SELECT TO authenticated USING ((user_id = auth.uid()));
CREATE POLICY "Users can request own deletion" ON public.account_deletion_requests AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((user_id = auth.uid()));
CREATE POLICY account_health_snapshot_staff_rw ON public.account_health_snapshot AS PERMISSIVE FOR ALL TO public USING ((vcaop_role() = ANY (ARRAY['staff'::text, 'admin'::text]))) WITH CHECK ((vcaop_role() = ANY (ARRAY['staff'::text, 'admin'::text])));
CREATE POLICY action_ledger_select_own ON public.action_ledger AS PERMISSIVE FOR SELECT TO authenticated USING ((user_id = auth.uid()));
CREATE POLICY action_ledger_service ON public.action_ledger AS PERMISSIVE FOR ALL TO service_role USING (true) WITH CHECK (true);
CREATE POLICY active_threads_tenant_user_isolation ON public.active_threads AS PERMISSIVE FOR ALL TO public USING (((tenant_id = COALESCE((current_setting('app.tenant_id'::text, true))::uuid, '00000000-0000-0000-0000-000000000000'::uuid)) AND (user_id = COALESCE((current_setting('app.user_id'::text, true))::uuid, '00000000-0000-0000-0000-000000000000'::uuid))));
CREATE POLICY admin_insights_service ON public.admin_insights AS PERMISSIVE FOR ALL TO service_role USING (true) WITH CHECK (true);
CREATE POLICY admin_insights_self_read ON public.admin_insights AS PERMISSIVE FOR SELECT TO authenticated USING ((tenant_id IN ( SELECT ut.tenant_id    FROM user_tenants ut   WHERE ((ut.user_id = auth.uid()) AND (ut.active_role = ANY (ARRAY['admin'::text, 'developer'::text, 'infra'::text]))))));
CREATE POLICY "Admins can manage proactive settings" ON public.admin_proactive_settings AS PERMISSIVE FOR ALL TO public USING (((COALESCE((((auth.jwt() -> 'app_metadata'::text) ->> 'exafy_admin'::text))::boolean, false) = true) OR (EXISTS ( SELECT 1    FROM memberships m   WHERE ((m.user_id = auth.uid()) AND (m.role = 'admin'::tenant_role) AND (m.status = 'active'::text))))));
CREATE POLICY "Anyone can view proactive settings" ON public.admin_proactive_settings AS PERMISSIVE FOR SELECT TO public USING (true);
CREATE POLICY affiliate_program_read ON public.affiliate_program AS PERMISSIVE FOR SELECT TO public USING ((vcaop_role() = ANY (ARRAY['staff'::text, 'admin'::text, 'developer'::text])));
